1	{
2	  "name": "meterwatch",
3	  "version": "0.0.0",
4	  "private": true,
5	  "type": "module",
6	  "engines": {
7	    "node": ">=24 <25"
8	  },
9	  "scripts": {
10	    "start": "node app.ts"
11	  }
12	}
13

1	// group schedule-report 子命令:按本地每周运行时间表把查询范围划分为运行与
2	// 非运行两类时段,分别核查分组能耗的只读报表,用于核查停运消耗。
3	//
4	// - 时间表为零个或多个每周窗口:开始星期 + 起止 HH:mm。开始限 00:00-23:59,
5	//   结束另可 24:00;同值起止拒绝;结束早于开始即跨至下一日(尾段沿用开始
6	//   日规则,周日可跨至周一)。窗口起点含、终点不含,重叠或重复取并集;空表
7	//   (零个窗口)表示全部非运行。
8	// - 分类按实际时刻的当地日期与墙钟:每秒只属一类;夏令时跳过时段不虚构
9	//   覆盖,回拨重复时段各自分类,不套固定偏移或日长。--tz 只解释时间表,
10	//   不重新解释起止时刻或已存读数。
11	// - 能耗口径与 group daily 相同:按当时生效成员与完整读数时序,全部成员
12	//   可信才累加消耗,任一成员下降优先为异常,否则任一成员未知为未知;首个
13	//   版本生效前、读数首末之外与孤立读数未知,不外推。采样限制按原始相邻
14	//   区间判断,裁切不使过长区间可信,等于限制仍可信;有效片段取原区间起点
15	//   累计比例向下取整的两端差,切分不重置起点;BigInt 精确计算,kWh 固定
16	//   三位小数。
17	// - 两类覆盖合计等于查询时长,消耗合计等于同范围、同限制的分组日报,拆开
18	//   查询相加一致;覆盖按时间计,不叠加成员秒数。
19	// - 只读:不改写时间表或业务存储,不自动评估;修正撤销后重查使用当前读数。
20	//   成功(含不可计算结果)返回 0;非法时间表返回 2;时间表文件不可读、未知
21	//   分组、所用存储损坏或全库重复读数身份返回 1,指出原因,不输出部分报表。
22	
23	import { readFileSync } from 'node:fs';
24	import { dataFilePath, groupFilePath, loadStore, StoreError, type Reading } from './store.ts';
25	import { formatIsoUtc, parseUtcDate } from './time.ts';
26	import { loadTimezone, wallSegments } from './tz.ts';
27	import { formatKwh } from './value.ts';
28	import { formatGapLine, maxIntervalText, mergeGaps, type GapDetail } from './report.ts';
29	import {
30	  computeGroupSegment,
31	  loadCheckedSeriesByDevice,
32	  loadGroups,
33	  type Group,
34	} from './groups.ts';
35	
36	function err(message: string): void {
37	  console.error(`meterwatch: ${message}`);
38	}
39	
40	export interface ScheduleWindow {
41	  /** 开始星期,0=周日 .. 6=周六。 */
42	  startDow: number;
43	  /** 开始当日的起始分钟,0..1439。 */
44	  startMin: number;
45	  /** 相对开始日的结束分钟(不含),恒大于 startMin;结束早于开始时 +1440 跨至下一日。 */
46	  endMin: number;
47	}
48	
49	const DOW_BY_NAME: Record<string, number> = {
50	  sun: 0,
51	  mon: 1,
52	  tue: 2,
53	  wed: 3,
54	  thu: 4,
55	  fri: 5,
56	  sat: 6,
57	};
58	
59	/** 星期序号的显示名(0=周日 .. 6=周六)。 */
60	const DOW_NAMES = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
61	
62	/** 一周分钟数(7 * 1440)。 */
63	const WEEK_MINUTES = 7 * 1440;
64	
65	/**
66	 * 单个窗口相对开始日的最大结束分钟(两天):分类只对每个当地日期回看
67	 * 上一日开始的窗口,故规范形窗口最长跨至下一日结束,更长的时间段必须
68	 * 拆成多个窗口表示。
69	 */
70	const MAX_WINDOW_END_MIN = 2 * 1440;
71	
72	/** 解析 HH:mm 为当日分钟数;allow24 时另接受 24:00(=1440)。无效返回 null。 */
73	function parseHm(raw: string, allow24: boolean): number | null {
74	  const m = /^(\d{2}):(\d{2})$/.exec(raw);
75	  if (!m) return null;
76	  const h = Number(m[1]);
77	  const mi = Number(m[2]);
78	  if (mi > 59) return null;
79	  if (h > 23) {
80	    if (allow24 && h === 24 && mi === 0) return 1440;
81	    return null;
82	  }
83	  return h * 60 + mi;
84	}
85	
86	/**
87	 * 解析每周运行时间表文本。每行一个窗口:<星期> <开始 HH:mm> <结束 HH:mm>;
88	 * 空行与 # 之后的注释忽略。星期为 mon..sun(不区分大小写)。开始限
89	 * 00:00-23:59,结束另可 24:00;同值起止拒绝;结束早于开始跨至下一日。
90	 * 重叠或重复窗口不在此拒绝,分类时取并集。非法时返回错误消息字符串。
91	 */
92	export function parseSchedule(text: string): ScheduleWindow[] | string {
93	  const windows: ScheduleWindow[] = [];
94	  const lines = text.split(/\r\n|\r|\n/);
95	  for (let i = 0; i < lines.length; i++) {
96	    const hash = lines[i].indexOf('#');
97	    const line = (hash === -1 ? lines[i] : lines[i].slice(0, hash)).trim();
98	    if (line === '') continue;
99	    const where = `line ${i + 1}`;
100	    const parts = line.split(/\s+/);
101	    if (parts.length !== 3) {
102	      return `${where}: expect '<weekday> <start HH:mm> <end HH:mm>' (weekday: mon..sun)`;
103	    }
104	    const dow = DOW_BY_NAME[parts[0].toLowerCase()];
105	    if (dow === undefined) {
106	      return `${where}: unknown weekday '${parts[0]}' (expect mon, tue, wed, thu, fri, sat or sun)`;
107	    }
108	    const start = parseHm(parts[1], false);
109	    if (start === null) {
110	      return `${where}: invalid start time '${parts[1]}' (expect HH:mm within 00:00-23:59)`;
111	    }
112	    const end = parseHm(parts[2], true);
113	    if (end === null) {
114	      return `${where}: invalid end time '${parts[2]}' (expect HH:mm within 00:00-24:00)`;
115	    }
116	    if (end === start) {
117	      return `${where}: start and end must differ (both are '${parts[1]}')`;
118	    }
119	    // 结束早于开始即跨至下一日,尾段沿用开始日规则(周日可跨至周一)。
120	    const endMin = end < start ? end + 1440 : end;
121	    windows.push({ startDow: dow, startMin: start, endMin });
122	  }
123	  return windows;
124	}
125	
126	/**
127	 * 把每周运行窗口规范化为并集的最简形式:按周分钟(0..10079)展开为覆盖
128	 * 集合(结束越过周界的窗口取模回卷),再合并为按周分钟升序、互不重叠、
129	 * 互不相邻的窗口列表;超过两天的连续覆盖按每个窗口最多跨至下一日结束
130	 * 切分(分类只回看上一日开始的窗口)。窗口顺序、重复与等价拆分(如
131	 * mon 08:00-12:00 加 mon 12:00-18:00 对比 mon 08:00-18:00)不影响规范形,
132	 * 故规范形相同当且仅当每周运行窗口的并集相同。空表(零个窗口)的规范形
133	 * 为空数组。
134	 */
135	export function canonicalizeWindows(windows: ScheduleWindow[]): ScheduleWindow[] {
136	  const covered = new Uint8Array(WEEK_MINUTES);
137	  for (const w of windows) {
138	    const s = w.startDow * 1440 + w.startMin;
139	    const e = w.startDow * 1440 + w.endMin;
140	    for (let m = s; m < e; m++) covered[m % WEEK_MINUTES] = 1;
141	  }
142	  const out: ScheduleWindow[] = [];
143	  let m = 0;
144	  while (m < WEEK_MINUTES) {
145	    if (covered[m] === 0) {
146	      m++;
147	      continue;
148	    }
149	    const s = m;
150	    while (m < WEEK_MINUTES && covered[m] === 1) m++;
151	    // 连续覆盖段 [s, m):切成每个窗口最多跨至下一日结束(分类只回看一天)。
152	    let cur = s;
153	    while (cur < m) {
154	      const startDow = Math.floor(cur / 1440);
155	      const end = Math.min(m, startDow * 1440 + MAX_WINDOW_END_MIN);
156	      out.push({ startDow, startMin: cur - startDow * 1440, endMin: end - startDow * 1440 });
157	      cur = end;
158	    }
159	  }
160	  return out;
161	}
162	
163	/**
164	 * 时间表的展示形式:`dow HH:mm-HH:mm` 列表(逗号分隔);结束可跨夜,
165	 * 小时可大于 24(相对开始日)。零个窗口显示为 `(no running windows)`。
166	 */
167	export function formatSchedule(windows: ScheduleWindow[]): string {
168	  if (windows.length === 0) return '(no running windows)';
169	  const hm = (min: number): string =>
170	    `${String(Math.floor(min / 60)).padStart(2, '0')}:${String(min % 60).padStart(2, '0')}`;
171	  return windows
172	    .map((w) => `${DOW_NAMES[w.startDow]} ${hm(w.startMin)}-${hm(w.endMin)}`)
173	    .join(', ');
174	}
175	
176	/**
177	 * 解析存储中的时间表字段(窗口数组,元素为 {startDow, startMin, endMin}):
178	 * startDow 0..6,startMin 0..1439,endMin 大于 startMin 且不超过两天(规范
179	 * 形窗口最多跨至下一日结束,与分类的回看口径一致)。非法返回 null,由
180	 * 调用方按损坏数据处理。
181	 */
182	export function validateStoredSchedule(value: unknown): ScheduleWindow[] | null {
183	  if (!Array.isArray(value)) return null;
184	  const out: ScheduleWindow[] = [];
185	  for (const w of value) {
186	    if (w === null || typeof w !== 'object') return null;
187	    const o = w as Record<string, unknown>;
188	    if (
189	      !Number.isSafeInteger(o.startDow) ||
190	      (o.startDow as number) < 0 ||
191	      (o.startDow as number) > 6 ||
192	      !Number.isSafeInteger(o.startMin) ||
193	      (o.startMin as number) < 0 ||
194	      (o.startMin as number) > 1439 ||
195	      !Number.isSafeInteger(o.endMin) ||
196	      (o.endMin as number) <= (o.startMin as number) ||
197	      (o.endMin as number) > MAX_WINDOW_END_MIN
198	    ) {
199	      return null;
200	    }
201	    out.push({
202	      startDow: o.startDow as number,
203	      startMin: o.startMin as number,
204	      endMin: o.endMin as number,
205	    });
206	  }
207	  return out;
208	}
209	
210	interface Period {
211	  /** 时段起点(含),epoch 秒。 */
212	  start: number;
213	  /** 时段终点(不含),epoch 秒。 */
214	  end: number;
215	}
216	
217	/** 墙钟午夜(按 UTC 解释的 epoch 秒)对应的星期,0=周日。1970-01-01 为周四。 */
218	function dowOfNaive(naiveMidnight: number): number {
219	  const days = Math.floor(naiveMidnight / 86400);
220	  return (((days + 4) % 7) + 7) % 7;
221	}
222	
223	/**
224	 * 把 [from, to) 按每周时间表分为运行与非运行两类实际 UTC 时段,两类合计
225	 * 恰好等于查询范围(每秒只属一类)。分类按实际时刻的当地日期与墙钟:
226	 * 墙钟段切分自命名时区(段内偏移恒定、当地日期单一),窗口墙钟区间与段
227	 * 墙钟区间求交后换算回 UTC;夏令时跳过的墙钟没有实际时刻,不虚构覆盖,
228	 * 回拨重复的墙钟两段实际时段各自分类,不套固定偏移或日长。
229	 */
230	export function classifyPeriods(
231	  fmt: Intl.DateTimeFormat,
232	  from: number,
233	  to: number,
234	  windows: ScheduleWindow[],
235	): { running: Period[]; nonRunning: Period[] } {
236	  const raw: Period[] = [];
237	  if (windows.length > 0) {
238	    // 各当地日期生效的窗口墙钟区间(按墙钟午夜缓存):本日开始的窗口,以及
239	    // 上一日开始、跨至本日的窗口尾段。
240	    const wallByDate = new Map<string, Array<[number, number]>>();
241	    const wallIntervalsOf = (label: string): Array<[number, number]> => {
242	      const cached = wallByDate.get(label);
243	      if (cached) return cached;
244	      const dayNaive = parseUtcDate(label) as number;
245	      const wall: Array<[number, number]> = [];
246	      for (const w of windows) {
247	        for (const startNaive of [dayNaive, dayNaive - 86400]) {
248	          if (dowOfNaive(startNaive) !== w.startDow) continue;
249	          wall.push([startNaive + w.startMin * 60, startNaive + w.endMin * 60]);
250	        }
251	      }
252	      wallByDate.set(label, wall);
253	      return wall;
254	    };
255	    for (const seg of wallSegments(fmt, from, to)) {
256	      const wall = wallIntervalsOf(seg.label);
257	      if (wall.length === 0) continue;
258	      // 段内偏移恒定,墙钟区间随 UTC 线性平移。
259	      const ws = seg.start + seg.offset;
260	      const we = seg.end + seg.offset;
261	      for (const [a, b] of wall) {
262	        const lo = Math.max(a, ws);
263	        const hi = Math.min(b, we);
264	        if (lo < hi) raw.push({ start: lo - seg.offset, end: hi - seg.offset });
265	      }
266	    }
267	    raw.sort((a, b) => a.start - b.start);
268	  }
269	  // 重叠或重复窗口取并集。
270	  const running: Period[] = [];
271	  for (const r of raw) {
272	    const last = running[running.length - 1];
273	    if (last && r.start <= last.end) {
274	      if (r.end > last.end) last.end = r.end;
275	    } else {
276	      running.push({ start: r.start, end: r.end });
277	    }
278	  }
279	  const nonRunning: Period[] = [];
280	  let cursor = from;
281	  for (const r of running) {
282	    if (cursor < r.start) nonRunning.push({ start: cursor, end: r.start });
283	    cursor = r.end;
284	  }
285	  if (cursor < to) nonRunning.push({ start: cursor, end: to });
286	  return { running, nonRunning };
287	}
288	
289	/**
290	 * 分组运行/非运行时段能耗报表:按本地每周运行时间表把 [from, to) 分为
291	 * 两类时段,分别按当时生效成员核查能耗。只读,不写入数据。返回进程退出码。
292	 */
293	export function cmdGroupScheduleReport(opts: {
294	  id: string;
295	  /** 本地每周运行时间表文件路径(只读)。 */
296	  schedulePath: string;
297	  from: number;
298	  to: number;
299	  /** 解释时间表的 IANA 时区;省略为 UTC。 */
300	  tz?: string;
301	  /** 最大采样间隔限制(正整数秒);省略表示无上限。只影响本次查询结果。 */
302	  maxInterval?: number;
303	}): number {
304	  const tzName = opts.tz ?? 'UTC';
305	  const tz = loadTimezone(tzName);
306	  if (!tz) {
307	    err(`unknown timezone '${tzName}' (expect an IANA timezone name supported by this runtime)`);
308	    return 2;
309	  }
310	
311	  let text: string;
312	  try {
313	    text = readFileSync(opts.schedulePath, 'utf8');
314	  } catch (e) {
315	    err(`cannot read schedule file ${opts.schedulePath}: ${(e as Error).message}`);
316	    return 1;
317	  }
318	  const parsed = parseSchedule(text);
319	  if (typeof parsed === 'string') {
320	    err(`invalid schedule file ${opts.schedulePath}: ${parsed}`);
321	    return 2;
322	  }
323	  const windows = parsed;
324	
325	  let groups: Group[];
326	  try {
327	    groups = loadGroups(groupFilePath());
328	  } catch (e) {
329	    if (e instanceof StoreError) {
330	      err(e.message);
331	      return 1;
332	    }
333	    throw e;
334	  }
335	  const group = groups.find((g) => g.id === opts.id);
336	  if (!group) {
337	    err(`unknown group '${opts.id}'`);
338	    return 1;
339	  }
340	
341	  let seriesByDevice: Map<string, Reading[]>;
342	  try {
343	    seriesByDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
344	  } catch (e) {
345	    if (e instanceof StoreError) {
346	      err(e.message);
347	      return 1;
348	    }
349	    throw e;
350	  }
351	
352	  const { running, nonRunning } = classifyPeriods(tz, opts.from, opts.to, windows);
353	
354	  console.log(`group: ${group.id}`);
355	  console.log(`schedule: ${opts.schedulePath} (${windows.length} window(s))`);
356	  console.log(`timezone: ${tzName}`);
357	  console.log(`max-interval: ${maxIntervalText(opts.maxInterval)}`);
358	
359	  const classes: Array<{ name: string; periods: Period[] }> = [
360	    { name: 'running', periods: running },
361	    { name: 'non-running', periods: nonRunning },
362	  ];
363	  let incomplete = false;
364	  const coverage: number[] = [];
365	  for (const c of classes) {
366	    let valid = 0;
367	    let anomaly = 0;
368	    let unknown = 0;
369	    let gapUnknown = 0;
370	    const gaps: GapDetail[] = [];
371	    let consumption = 0n;
372	    for (const p of c.periods) {
373	      const stats = computeGroupSegment(
374	        group.versions,
375	        seriesByDevice,
376	        p.start,
377	        p.end,
378	        opts.maxInterval,
379	      );
380	      valid += stats.valid;
381	      anomaly += stats.anomaly;
382	      unknown += stats.unknown;
383	      gapUnknown += stats.gapUnknown;
384	      mergeGaps(gaps, stats.gaps);
385	      consumption += stats.consumption;
386	    }
387	    let seconds = 0;
388	    for (const p of c.periods) seconds += p.end - p.start;
389	    coverage.push(seconds);
390	    const classIncomplete = anomaly > 0 || unknown > 0;
391	    if (classIncomplete) incomplete = true;
392	
393	    const consumptionText =
394	      valid > 0
395	        ? `consumption=${formatKwh(consumption)} kWh (estimate)`
396	        : 'consumption=n/a (no valid coverage)';
397	    let line =
398	      `  class=${c.name}  ${consumptionText}` +
399	      `  valid=${valid}s  anomaly=${anomaly}s  unknown=${unknown}s`;
400	    if (opts.maxInterval !== undefined) line += `  gap=${gapUnknown}s`;
401	    if (classIncomplete) line += '  INCOMPLETE';
402	    console.log(line);
403	    for (const p of c.periods) {
404	      console.log(`    period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`);
405	    }
406	    for (const g of gaps) {
407	      console.log(formatGapLine(g));
408	    }
409	  }
410	
411	  const status = incomplete
412	    ? 'status=INCOMPLETE (unknown or anomaly coverage present)'
413	    : 'status=complete';
414	  console.log(
415	    `  summary: group=${group.id}  running=${coverage[0]}s  non-running=${coverage[1]}s` +
416	      `  total=${opts.to - opts.from}s  ${status}`,
417	  );
418	  return 0;
419	}
420

