153	/**
154	 * 每周运行窗口并集等价性:两边都取规范形后逐窗口比较。窗口顺序、重复及
155	 * 等价拆分不影响等价性;不比较任何文件路径。两边都省略(全天模式)才相等。
156	 */
157	function scheduleEquals(a?: ScheduleWindow[], b?: ScheduleWindow[]): boolean {
158	  if (a === undefined || b === undefined) return a === b;
159	  const ca = canonicalizeWindows(a);
160	  const cb = canonicalizeWindows(b);
161	  return (
162	    ca.length === cb.length &&
163	    ca.every(
164	      (w, i) =>
165	        w.startDow === cb[i].startDow && w.startMin === cb[i].startMin && w.endMin === cb[i].endMin,
166	    )
167	  );
168	}
