170	/**
171	 * 解析告警存储的 JSON 结构。结构非法抛出 StoreError;source 用于错误消息
172	 * (如 `storage file <path>`)。旧版仅含 device 字段、无时区的规则按 UTC 读入。
173	 */
174	export function parseAlertState(data: unknown, source: string): AlertState {
175	  const bad = (what: string): StoreError =>
176	    new StoreError(`${source} is corrupted (${what})`);
177	  const o = data as Record<string, unknown>;
178	  if (o === null || typeof o !== 'object') throw bad('not an object');
179	  if (!Number.isSafeInteger(o.nextAlertNum) || (o.nextAlertNum as number) < 1) {
180	    throw bad('invalid nextAlertNum');
181	  }
182	  if (!Number.isSafeInteger(o.nextEventSeq) || (o.nextEventSeq as number) < 1) {
183	    throw bad('invalid nextEventSeq');
184	  }
185	  if (!Array.isArray(o.rules)) throw bad('missing rules array');
186	  if (!Array.isArray(o.alerts)) throw bad('missing alerts array');
187	
188	  const ruleIds = new Set<string>();
189	  const rules: AlertRule[] = [];
190	  for (const r of o.rules as Array<Record<string, unknown>>) {
191	    // 阈值兼容旧格式的安全整数数值;超出安全整数范围的数值型阈值精度已丢失,
192	    // 按损坏数据拒绝,不猜测原值。
193	    const thresholdMilli = r !== null && typeof r === 'object' ? parseStoredMilli(r.thresholdMilli) : null;
194	    if (
195	      r === null ||
196	      typeof r !== 'object' ||
197	      typeof r.id !== 'string' ||
198	      r.id.length === 0 ||
199	      thresholdMilli === null
200	    ) {
201	      throw bad('invalid rule entry');
202	    }
203	    // 目标类型:新版字段 targetType/targetId;旧版只有 device 字段,按 device 规则
204	    // 读入,已有设备规则无需手工转换即可继续使用。
205	    let targetType: RuleTargetType;
206	    let targetId: string;
207	    if (r.targetType === undefined) {
208	      if (typeof r.device !== 'string' || r.device.length === 0) throw bad('invalid rule entry');
209	      targetType = 'device';
210	      targetId = r.device;
211	    } else {
212	      if (r.targetType !== 'device' && r.targetType !== 'group') {
213	        throw bad(`invalid targetType in rule '${r.id}'`);
214	      }
215	      if (typeof r.targetId !== 'string' || r.targetId.length === 0) {
216	        throw bad(`invalid targetId in rule '${r.id}'`);
217	      }
218	      targetType = r.targetType;
219	      targetId = r.targetId;
220	    }
221	    // 时区:新版字段 tz 存规范 IANA 名;旧版无时区的规则按 UTC 使用。存储内
222	    // 非法时区按损坏数据拒绝,不能回退为 UTC;合法写法统一解析为规范名。
223	    let tz = 'UTC';
224	    if (r.tz !== undefined) {
225	      if (typeof r.tz !== 'string' || r.tz.length === 0) {
226	        throw bad(`invalid timezone in rule '${r.id}'`);
227	      }
228	      const canonical = canonicalTimezone(r.tz);
229	      if (canonical === null) throw bad(`invalid timezone in rule '${r.id}'`);
230	      tz = canonical;
231	    }
232	    // 采样间隔限制:新版字段 maxInterval 存正整数秒;旧版无该字段的规则按
233	    // 无上限使用。存储内非法限制按损坏数据拒绝,不能悄悄忽略。
234	    let maxInterval: number | undefined;
235	    if (r.maxInterval !== undefined) {
236	      if (!Number.isSafeInteger(r.maxInterval) || (r.maxInterval as number) < 1) {
237	        throw bad(`invalid maxInterval in rule '${r.id}'`);
238	      }
239	      maxInterval = r.maxInterval as number;
240	    }
241	    // 模式与时间表:新版字段 mode/schedule;旧版无该字段的规则按全天模式
242	    // 使用。非法已存模式或时间表按损坏数据拒绝;非运行模式只适用于分组
243	    // 规则,全天模式不得带时间表。
244	    const mode = r.mode === undefined ? 'all-day' : r.mode;
245	    if (mode !== 'all-day' && mode !== 'non-running') {
246	      throw bad(`invalid mode in rule '${r.id}'`);
247	    }
248	    let schedule: ScheduleWindow[] | undefined;
249	    if (mode === 'non-running') {
250	      if (targetType !== 'group') throw bad(`non-running mode on device rule '${r.id}'`);
251	      const parsed = validateStoredSchedule(r.schedule);
252	      if (parsed === null) throw bad(`invalid schedule in rule '${r.id}'`);
253	      schedule = parsed;
254	    } else if (r.schedule !== undefined) {
255	      throw bad(`unexpected schedule in all-day rule '${r.id}'`);
256	    }
257	    if (ruleIds.has(r.id)) throw bad(`duplicate rule id '${r.id}'`);
258	    ruleIds.add(r.id);
259	    rules.push({
260	      id: r.id,
261	      targetType,
262	      targetId,
263	      thresholdMilli: thresholdMilli as bigint,
264	      tz,
265	      maxInterval,
266	      schedule,
267	    });
268	  }
269	
270	  const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
271	  const alertIds = new Set<string>();
272	  for (const a of o.alerts as Array<Record<string, unknown>>) {
273	    const ok =
274	      a !== null &&
275	      typeof a === 'object' &&
276	      typeof a.id === 'string' &&
277	      a.id.length > 0 &&
278	      typeof a.ruleId === 'string' &&
279	      ruleIds.has(a.ruleId) &&
280	      typeof a.date === 'string' &&
281	      DATE_RE.test(a.date) &&
282	      (a.status === 'triggered' || a.status === 'recovered') &&
283	      typeof a.acknowledged === 'boolean' &&
284	      Array.isArray(a.events) &&
285	      (a.events as unknown[]).length > 0;
286	    if (!ok) throw bad('invalid alert entry');
287	    if (alertIds.has(a.id)) throw bad(`duplicate alert id '${a.id}'`);
288	    alertIds.add(a.id);
289	    const seqs = new Set<number>();
290	    for (const e of a.events as Array<Record<string, unknown>>) {
291	      const eok =
292	        e !== null &&
293	        typeof e === 'object' &&
294	        Number.isSafeInteger(e.seq) &&
295	        (e.seq as number) >= 1 &&
296	        (e.type === 'triggered' || e.type === 'recovered' || e.type === 'acknowledged') &&
297	        (e.consumptionMilli === undefined ||
298	          (typeof e.consumptionMilli === 'string' && /^\d+$/.test(e.consumptionMilli)));
299	      if (!eok) throw bad('invalid alert event');
300	      if (seqs.has(e.seq as number)) throw bad(`duplicate event seq in alert '${a.id}'`);
301	      seqs.add(e.seq as number);
302	    }
303	  }
304	  return {
305	    nextAlertNum: o.nextAlertNum as number,
306	    nextEventSeq: o.nextEventSeq as number,
307	    rules,
308	    alerts: o.alerts as unknown as AlertRecord[],
309	  };
310	}
