312	/** 读取告警存储;文件不存在返回空状态,存在但无法读取或内容损坏抛出 StoreError。 */
313	export function loadAlertState(path: string): AlertState {
314	  let text: string;
315	  try {
316	    text = readFileSync(path, 'utf8');
317	  } catch (e) {
318	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyState();
319	    throw new StoreError(`cannot read storage file ${path}: ${(e as Error).message}`);
320	  }
321	  let data: unknown;
322	  try {
323	    data = JSON.parse(text);
324	  } catch {
325	    throw new StoreError(`storage file ${path} is corrupted (invalid JSON)`);
326	  }
327	  return parseAlertState(data, `storage file ${path}`);
328	}
