330	/** 序列化为告警存储文件的 JSON 结构(阈值为十进制字符串,任意大数精确)。 */
331	export function serializeAlertState(state: AlertState): Record<string, unknown> {
332	  return {
333	    version: 2,
334	    ...state,
335	    rules: state.rules.map((r) => ({
336	      id: r.id,
337	      targetType: r.targetType,
338	      targetId: r.targetId,
339	      thresholdMilli: r.thresholdMilli.toString(),
340	      tz: r.tz,
341	      ...(r.maxInterval !== undefined ? { maxInterval: r.maxInterval } : {}),
342	      ...(r.schedule !== undefined ? { mode: 'non-running', schedule: r.schedule } : {}),
343	    })),
344	  };
345	}
