347	/**
348	 * 原子写入告警存储;失败抛错,原有数据保持不变。
349	 * 告警写入不触碰读数与成员版本文件。
350	 */
351	function saveAlertState(path: string, state: AlertState): void {
352	  mkdirSync(dirname(path), { recursive: true });
353	  const tmp = `${path}.tmp-${process.pid}`;
354	  const body = JSON.stringify(serializeAlertState(state), null, 2) + '\n';
355	  try {
356	    writeFileSync(tmp, body, 'utf8');
357	    renameSync(tmp, path);
358	  } catch (e) {
359	    throw new StoreError(`cannot write storage file ${path}: ${(e as Error).message}`);
360	  }
361	}
