363	/**
364	 * 载入读数并取出指定设备的完整时序(按时刻排序)。
365	 * 同设备同一实际时刻存在多条存储记录时抛 StoreError。
366	 */
367	function deviceSeries(device: string): Reading[] {
368	  const all = loadStore(dataFilePath());
369	  const series = all.filter((r) => r.device === device).sort((a, b) => a.ts - b.ts);
370	  for (let i = 1; i < series.length; i++) {
371	    if (series[i].ts === series[i - 1].ts) {
372	      throw new StoreError(
373	        `storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(series[i].ts)}`,
374	      );
375	    }
376	  }
377	  return series;
378	}
