380	/**
381	 * 分组规则的评估环境:绑定分组与全库设备时序。
382	 * 读取读数时拒绝全库重复身份,包括不属于该分组的设备。
383	 */
384	interface GroupEnv {
385	  kind: 'group';
386	  group: Group;
387	  byDevice: Map<string, Reading[]>;
388	}
389	
390	interface DeviceEnv {
391	  kind: 'device';
392	  series: Reading[];
393	}
394	
395	type RuleEnv = DeviceEnv | GroupEnv;
396	
397	/** 为规则准备评估环境;未知分组或存储损坏抛 StoreError。 */
398	function prepareEnv(rule: AlertRule): RuleEnv {
399	  if (rule.targetType === 'device') {
400	    return { kind: 'device', series: deviceSeries(rule.targetId) };
401	  }
402	  const groups = loadGroups(groupFilePath());
403	  const group = groups.find((g) => g.id === rule.targetId);
404	  if (!group) {
405	    throw new StoreError(
406	      `unknown group '${rule.targetId}' bound by rule '${rule.id}' (groups storage has no such group)`,
407	    );
408	  }
409	  const byDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
410	  return { kind: 'group', group, byDevice };
411	}
