413	/** 一天的有效/异常/未知覆盖秒数后缀;采用间隔限制时附上过长间隔造成的未知秒数。 */
414	function coverageSuffix(
415	  stats: Pick<DayStats, 'valid' | 'anomaly' | 'unknown' | 'gapUnknown'>,
416	  limited: boolean,
417	): string {
418	  const base = `valid=${stats.valid}s anomaly=${stats.anomaly}s unknown=${stats.unknown}s`;
419	  return limited ? `${base} gap=${stats.gapUnknown}s` : base;
420	}
