422	/** 一天各实际 UTC 时段的展示行(时段按实际时刻升序)。 */
423	function periodLines(periods: LocalDayPeriod[]): string[] {
424	  return periods.map((p) => `    period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`);
425	}
426	
427	/** 一天内过长区间明细的展示行(指出相关设备与原始相邻读数时刻)。 */
428	function gapLines(stats: Pick<DayStats, 'gaps'>, rule: AlertRule): string[] {
429	  return stats.gaps.map((g) => formatGapLine(g, rule.targetType === 'device' ? rule.targetId : undefined));
430	}
