432	/** 规则时区的墙钟格式化器;存储载入时已校验,此处不会失败。 */
433	function ruleFormat(rule: AlertRule): Intl.DateTimeFormat {
434	  const fmt = loadTimezone(rule.tz);
435	  if (fmt === null) {
436	    throw new StoreError(`rule '${rule.id}' has invalid timezone '${rule.tz}' in storage`);
437	  }
438	  return fmt;
439	}
