441	/**
442	 * 规则在一个当地日期上实际参与判定的 UTC 时段:全天模式为该日期的全部
443	 * 实际时段;非运行模式为这些时段按规则固定的每周运行时间表分类后的非
444	 * 运行部分(分类沿用 group schedule-report 的口径:按实际时刻的当地日期
445	 * 与墙钟,回拨重复小时各自分类,跳过时段不虚构)。同一日期的不连续时段
446	 * 分别分类后合并在同一日期下参与一次判定。
447	 */
448	function ruleDayPeriods(rule: AlertRule, fmt: Intl.DateTimeFormat, day: LocalDay): LocalDayPeriod[] {
449	  if (rule.schedule === undefined) return day.periods;
450	  const out: LocalDayPeriod[] = [];
451	  for (const p of day.periods) {
452	    out.push(...classifyPeriods(fmt, p.start, p.end, rule.schedule).nonRunning);
453	  }
454	  return out;
455	}
456	
457	/**
458	 * 计算规则在给定 UTC 时段集合上的统计(这些时段属于同一当地日期)。
459	 * 设备规则用 daily 口径,分组规则用 group daily 的联合覆盖口径;
460	 * 日界线、时间表边界与成员切换都不重置各设备原读数区间的分摊起点。
461	 * maxInterval 为规则固定的采样间隔限制(省略为无上限)。
462	 */
463	function computeRuleDay(env: RuleEnv, periods: LocalDayPeriod[], maxInterval?: number): DayStats {
464	  let valid = 0;
465	  let anomaly = 0;
466	  let unknown = 0;
467	  let gapUnknown = 0;
468	  const gaps: GapDetail[] = [];
469	  let consumption = 0n;
470	  for (const p of periods) {
471	    if (env.kind === 'device') {
472	      const s = computeDay(env.series, p.start, p.end, maxInterval);
473	      valid += s.valid;
474	      anomaly += s.anomaly;
475	      unknown += s.unknown;
476	      gapUnknown += s.gapUnknown;
477	      mergeGaps(gaps, s.gaps);
478	      consumption += s.consumption;
479	    } else {
480	      const s = computeGroupSegment(env.group.versions, env.byDevice, p.start, p.end, maxInterval);
481	      valid += s.valid;
482	      anomaly += s.anomaly;
483	      unknown += s.unknown;
484	      gapUnknown += s.gapUnknown;
485	      mergeGaps(gaps, s.gaps);
486	      consumption += s.consumption;
487	    }
488	  }
489	  return { valid, anomaly, unknown, gapUnknown, gaps, consumption };
490	}
