492	/**
493	 * 创建规则。相同标识、同目标类型、同目标标识、等价阈值、同时区(规范名)、
494	 * 同采样间隔限制及同模式(非运行模式比较每周运行窗口并集,不比较文件路径)
495	 * 重试成功且不重复创建;任一不同即报冲突。设备必须已有存储读数;分组必须
496	 * 已配置。非运行模式(带固定时间表,仅分组规则)的创建与同参重试都先检查
497	 * 所用存储与全库重复读数身份。返回进程退出码。
498	 */
499	export function cmdRuleCreate(opts: {
500	  id: string;
501	  targetType: RuleTargetType;
502	  targetId: string;
503	  thresholdMilli: bigint;
504	  /** 规范 IANA 时区名(调用方已解析;省略时传 'UTC')。 */
505	  tz: string;
506	  /** 最大采样间隔限制(正整数秒);省略表示无上限,创建后固定。 */
507	  maxInterval?: number;
508	  /** 非运行模式的每周运行时间表(已解析并规范化的窗口并集);省略为全天
509	   *  模式。仅分组规则可带;创建时保存解析结果,与原文件后续变化无关。 */
510	  schedule?: ScheduleWindow[];
511	}): number {
512	  const statePath = alertFilePath();
513	  let state: AlertState;
514	  try {
515	    state = loadAlertState(statePath);
516	  } catch (e) {
517	    if (e instanceof StoreError) {
518	      err(e.message);
519	      return 1;
520	    }
521	    throw e;
522	  }
523	
524	  // 非运行模式:新模式创建与同参重试都先检查所用存储(分组、读数)及全库
525	  // 重复读数身份,再比较参数或写入。
526	  let groups: Group[] | undefined;
527	  if (opts.schedule !== undefined) {
528	    try {
529	      groups = loadGroups(groupFilePath());
530	      loadCheckedSeriesByDevice(loadStore(dataFilePath()));
531	    } catch (e) {
532	      if (e instanceof StoreError) {
533	        err(e.message);
534	        return 1;
535	      }
536	      throw e;
537	    }
538	  }
539	
540	  const got = `${opts.targetType}=${opts.targetId}`;
541	  const existing = state.rules.find((r) => r.id === opts.id);
542	  if (existing) {
543	    if (
544	      existing.targetType === opts.targetType &&
545	      existing.targetId === opts.targetId &&
546	      existing.thresholdMilli === opts.thresholdMilli &&
547	      existing.tz === opts.tz &&
548	      existing.maxInterval === opts.maxInterval &&
549	      scheduleEquals(existing.schedule, opts.schedule)
550	    ) {
551	      console.log(
552	        `rule '${opts.id}' already exists with identical parameters (${targetLabel(existing)} ` +
553	          `threshold=${formatKwh(existing.thresholdMilli)} kWh tz=${existing.tz} ` +
554	          `max-interval=${maxIntervalText(existing.maxInterval)} ${modeText(existing)}); unchanged`,
555	      );
556	      return 0;
557	    }
558	    err(
559	      `rule '${opts.id}' already exists with different parameters ` +
560	        `(stored ${targetLabel(existing)} threshold=${formatKwh(existing.thresholdMilli)} kWh ` +
561	        `tz=${existing.tz} max-interval=${maxIntervalText(existing.maxInterval)} ${modeText(existing)}, ` +
562	        `got ${got} threshold=${formatKwh(opts.thresholdMilli)} kWh ` +
563	        `tz=${opts.tz} max-interval=${maxIntervalText(opts.maxInterval)} ${modeText(opts)}); conflict`,
564	    );
565	    return 1;
566	  }
567	
568	  // 目标存在性:设备需已有存储读数;分组需已配置(配置时已保证成员设备存在)。
569	  try {
570	    if (opts.targetType === 'device') {
571	      const devices = new Set(loadStore(dataFilePath()).map((r) => r.device));
572	      if (!devices.has(opts.targetId)) {
573	        err(`unknown device '${opts.targetId}': no stored readings; import readings before creating a rule`);
574	        return 1;
575	      }
576	    } else {
577	      const known = groups ?? loadGroups(groupFilePath());
578	      if (!known.some((g) => g.id === opts.targetId)) {
579	        err(`unknown group '${opts.targetId}': configure the group before creating a rule`);
580	        return 1;
581	      }
582	    }
583	  } catch (e) {
584	    if (e instanceof StoreError) {
585	      err(e.message);
586	      return 1;
587	    }
588	    throw e;
589	  }
590	
591	  state.rules.push({
592	    id: opts.id,
593	    targetType: opts.targetType,
594	    targetId: opts.targetId,
595	    thresholdMilli: opts.thresholdMilli,
596	    tz: opts.tz,
597	    maxInterval: opts.maxInterval,
598	    schedule: opts.schedule,
599	  });
600	  try {
601	    saveAlertState(statePath, state);
602	  } catch (e) {
603	    if (e instanceof StoreError) {
604	      err(e.message);
605	      return 1;
606	    }
607	    throw e;
608	  }
609	  console.log(
610	    `rule '${opts.id}' created: ${got} threshold=${formatKwh(opts.thresholdMilli)} kWh ` +
611	      `tz=${opts.tz} max-interval=${maxIntervalText(opts.maxInterval)} ${modeText(opts)}`,
612	  );
613	  return 0;
614	}
615	
616	/** 列出全部规则(含目标类型、时区、采样间隔限制、模式及固定时间表)。只读。返回进程退出码。 */
617	export function cmdRuleList(): number {
618	  let state: AlertState;
619	  try {
620	    state = loadAlertState(alertFilePath());
621	  } catch (e) {
622	    if (e instanceof StoreError) {
623	      err(e.message);
624	      return 1;
625	    }
626	    throw e;
627	  }
628	  if (state.rules.length === 0) {
629	    console.log('no rules defined');
630	    return 0;
631	  }
632	  const rules = [...state.rules].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
633	  for (const r of rules) {
634	    const open = state.alerts.filter((a) => a.ruleId === r.id && a.status === 'triggered').length;
635	    console.log(
636	      `rule ${r.id}  ${targetLabel(r)}  threshold=${formatKwh(r.thresholdMilli)} kWh  ` +
637	        `tz=${r.tz}  max-interval=${maxIntervalText(r.maxInterval)}  ${modeText(r)}  open alerts=${open}`,
638	    );
639	  }
640	  return 0;
641	}
642	
643	/**
644	 * 评估规则在连续完整当地日期范围 [from, to)(规则时区的 YYYY-MM-DD,起日含、
645	 * 止日不含)上的超限情况。每个日期统计归属该日期的全部实际 UTC 时段,一次
646	 * 评估只作一次判定;整日被跳过的日期标明跳过,不判定、不创建也不恢复告警。
647	 * 非运行模式的规则每天只取这些时段中的非运行部分参与判定(运行时段的异常
648	 * 或未知不阻止判定);没有非运行秒数的日期标明原因,同样不判定、不创建也
649	 * 不恢复。全部日期计算并应用到内存状态后一次性原子写入,不部分提交;中途
650	 * 任一存储或数据错误都在写入前抛出,操作前状态保留。返回进程退出码。
651	 */
652	export function cmdEvaluate(opts: { ruleId: string; from: string; to: string }): number {
653	  const statePath = alertFilePath();
654	  let state: AlertState;
655	  let rule: AlertRule;
656	  let env: RuleEnv;
657	  let fmt: Intl.DateTimeFormat;
658	  try {
659	    state = loadAlertState(statePath);
660	    const found = state.rules.find((r) => r.id === opts.ruleId);
661	    if (!found) {
662	      err(`unknown rule '${opts.ruleId}'`);
663	      return 1;
664	    }
665	    rule = found;
666	    env = prepareEnv(rule);
667	    fmt = ruleFormat(rule);
668	  } catch (e) {
669	    if (e instanceof StoreError) {
670	      err(e.message);
671	      return 1;
672	    }
673	    throw e;
674	  }
675	
676	  // 既有告警标识集合:新标识不得与旧告警冲突(正常情况下编号单调递增不可能
677	  // 碰撞,这里再显式防御,碰撞则整体中止且不写入)。
678	  const alertIds = new Set(state.alerts.map((a) => a.id));
679	
680	  const threshold = rule.thresholdMilli;
681	  const limited = rule.maxInterval !== undefined;
682	  const lines: string[] = [];
683	  for (const { label, day } of localDateRange(fmt, opts.from, opts.to)) {
684	    if (day === null) {
685	      // 整日被跳过(无实际时段):不判定、不触发也不恢复。
686	      lines.push(`  ${label}  SKIPPED (no such local date in timezone ${rule.tz})  no alert action`);
687	      continue;
688	    }
689	    // 全天模式为当天全部实际时段;非运行模式只取其中的非运行部分。
690	    const periods = ruleDayPeriods(rule, fmt, day);
691	    let periodSeconds = 0;
692	    for (const p of periods) periodSeconds += p.end - p.start;
693	    if (periodSeconds === 0) {
694	      // 非运行模式且当天没有非运行秒数:说明原因,不判定、不触发也不恢复。
695	      lines.push(
696	        `  ${label}  NO NON-RUNNING COVERAGE (running windows cover the whole local date)  no alert action`,
697	      );
698	      continue;
699	    }
700	    const stats = computeRuleDay(env, periods, rule.maxInterval);
701	    const coverage = coverageSuffix(stats, limited);
702	    if (stats.unknown > 0 || stats.anomaly > 0) {
703	      // 有未知或下降覆盖:不可判定,不触发也不恢复。
704	      lines.push(`  ${label}  undecidable (${coverage})  no alert action`);
705	      lines.push(...periodLines(periods));
706	      lines.push(...gapLines(stats, rule));
707	      continue;
708	    }
709	    const exceeded = stats.consumption > threshold;
710	    const cmp =
711	      `consumption=${formatKwh(stats.consumption)} kWh ` +
712	      `${exceeded ? '>' : '<='} threshold=${formatKwh(rule.thresholdMilli)} kWh`;
713	    const open = state.alerts.find(
714	      (a) => a.ruleId === rule.id && a.date === label && a.status === 'triggered',
715	    );
716	    if (exceeded) {
717	      if (open) {
718	        // 重复超限:保留原标识,不新增事件。
719	        lines.push(`  ${label}  ${cmp}  EXCEEDED  alert ${open.id} remains triggered  ${coverage}`);
720	      } else {
721	        const id = `alert-${state.nextAlertNum++}`;
722	        if (alertIds.has(id)) {
723	          err(`storage error: generated alert id '${id}' already exists; nothing was written`);
724	          return 1;
725	        }
726	        alertIds.add(id);
727	        state.alerts.push({
728	          id,
729	          ruleId: rule.id,
730	          date: label,
731	          status: 'triggered',
732	          acknowledged: false,
733	          events: [
734	            { seq: state.nextEventSeq++, type: 'triggered', consumptionMilli: stats.consumption.toString() },
735	          ],
736	        });
737	        lines.push(`  ${label}  ${cmp}  EXCEEDED  alert ${id} triggered (unacknowledged)  ${coverage}`);
738	      }
739	    } else {
740	      if (open) {
741	        open.status = 'recovered';
742	        open.events.push({
743	          seq: state.nextEventSeq++,
744	          type: 'recovered',
745	          consumptionMilli: stats.consumption.toString(),
746	        });
747	        lines.push(`  ${label}  ${cmp}  NORMAL  alert ${open.id} recovered  ${coverage}`);
748	      } else {
749	        lines.push(`  ${label}  ${cmp}  NORMAL  no alert  ${coverage}`);
750	      }
751	    }
752	    lines.push(...periodLines(periods));
753	  }
754	
755	  try {
756	    saveAlertState(statePath, state);
757	  } catch (e) {
758	    if (e instanceof StoreError) {
759	      err(e.message);
760	      return 1;
761	    }
762	    throw e;
763	  }
764	
765	  console.log(
766	    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh  ` +
767	      `tz=${rule.tz}  max-interval=${maxIntervalText(rule.maxInterval)}  ${modeText(rule)}`,
768	  );
769	  for (const line of lines) console.log(line);
770	  return 0;
771	}
772	
773	/**
774	 * 查询规则的告警历史。只读,不修改数据,也不会隐式恢复。
775	 * 给定日期范围时按规则时区的当地日期逐日展示当前计算的消耗或不可判定原因、
776	 * 实际 UTC 时段与各次告警;省略范围时展示有告警记录的全部日期。触发/恢复
777	 * 事件中的消耗为评估当时记录,不随后续数据变化改写。返回进程退出码。
778	 */
779	export function cmdAlerts(opts: { ruleId: string; from?: string; to?: string }): number {
780	  let state: AlertState;
781	  let rule: AlertRule;
782	  let env: RuleEnv;
783	  let fmt: Intl.DateTimeFormat;
784	  try {
785	    state = loadAlertState(alertFilePath());
786	    const found = state.rules.find((r) => r.id === opts.ruleId);
787	    if (!found) {
788	      err(`unknown rule '${opts.ruleId}'`);
789	      return 1;
790	    }
791	    rule = found;
792	    env = prepareEnv(rule);
793	    fmt = ruleFormat(rule);
794	  } catch (e) {
795	    if (e instanceof StoreError) {
796	      err(e.message);
797	      return 1;
798	    }
799	    throw e;
800	  }
801	
802	  // 待展示的当地日期(升序):给定范围时为范围内全部日期;省略范围时为有告警
803	  // 记录的全部日期。
804	  let labels: string[];
805	  if (opts.from !== undefined && opts.to !== undefined) {
806	    labels = localDateRange(fmt, opts.from, opts.to).map((e) => e.label);
807	  } else {
808	    labels = [
809	      ...new Set(state.alerts.filter((a) => a.ruleId === rule.id).map((a) => a.date)),
810	    ].sort();
811	  }
812	
813	  console.log(
814	    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh  ` +
815	      `tz=${rule.tz}  max-interval=${maxIntervalText(rule.maxInterval)}  ${modeText(rule)}`,
816	  );
817	  if (labels.length === 0) {
818	    console.log(`  no alerts recorded for rule '${rule.id}'`);
819	    return 0;
820	  }
821	
822	  // 各当地日期的实际 UTC 时段;整日被跳过的日期为 null。日历日期逐日递增,
823	  // 末日后延一天作为切分终点。
824	  const last = parseUtcDate(labels[labels.length - 1]) as number;
825	  const endLabel = formatIsoUtc(last + DAY_SECONDS).slice(0, 10);
826	  const byLabel = new Map<string, LocalDay | null>();
827	  for (const e of localDateRange(fmt, labels[0], endLabel)) byLabel.set(e.label, e.day);
828	
829	  const threshold = rule.thresholdMilli;
830	  const limited = rule.maxInterval !== undefined;
831	  for (const label of labels) {
832	    const day = byLabel.get(label) ?? null;
833	    if (day === null) {
834	      console.log(`  ${label}  SKIPPED (no such local date in timezone ${rule.tz})`);
835	    } else {
836	      // 全天模式为当天全部实际时段;非运行模式只取其中的非运行部分。
837	      const periods = ruleDayPeriods(rule, fmt, day);
838	      let periodSeconds = 0;
839	      for (const p of periods) periodSeconds += p.end - p.start;
840	      if (periodSeconds === 0) {
841	        console.log(`  ${label}  NO NON-RUNNING COVERAGE (running windows cover the whole local date)`);
842	      } else {
843	        const stats = computeRuleDay(env, periods, rule.maxInterval);
844	        if (stats.unknown > 0 || stats.anomaly > 0) {
845	          console.log(`  ${label}  undecidable (${coverageSuffix(stats, limited)})`);
846	        } else {
847	          const verdict = stats.consumption > threshold ? 'EXCEEDED' : 'NORMAL';
848	          console.log(
849	            `  ${label}  consumption=${formatKwh(stats.consumption)} kWh ` +
850	              `(${verdict}, threshold=${formatKwh(rule.thresholdMilli)} kWh)  ${coverageSuffix(stats, limited)}`,
851	          );
852	        }
853	        for (const line of periodLines(periods)) console.log(line);
854	        for (const line of gapLines(stats, rule)) console.log(line);
855	      }
856	    }
857	    const alerts = state.alerts
858	      .filter((a) => a.ruleId === rule.id && a.date === label)
859	      .sort((a, b) => a.events[0].seq - b.events[0].seq);
860	    if (alerts.length === 0) {
861	      console.log('    no alerts');
862	      continue;
863	    }
864	    for (const a of alerts) {
865	      console.log(
866	        `    alert ${a.id}  status=${a.status.toUpperCase()}  ` +
867	          `ack=${a.acknowledged ? 'ACKNOWLEDGED' : 'UNACKNOWLEDGED'}`,
868	      );
869	      const events = a.events
870	        .map((e) => {
871	          const consumption =
872	            e.consumptionMilli !== undefined
873	              ? ` (consumption=${formatKwh(BigInt(e.consumptionMilli))} kWh)`
874	              : '';
875	          return `#${e.seq} ${e.type}${consumption}`;
876	        })
877	        .join(', ');
878	      console.log(`      events: ${events}`);
879	    }
880	  }
881	  return 0;
882	}
883	
884	/**
885	 * 按标识确认告警。已恢复告警也可确认;重复确认成功且不重复记事;
886	 * 确认不改变超限或恢复状态。返回进程退出码。
887	 */
888	export function cmdAck(alertId: string): number {
889	  const statePath = alertFilePath();
890	  let state: AlertState;
891	  try {
892	    state = loadAlertState(statePath);
893	  } catch (e) {
894	    if (e instanceof StoreError) {
895	      err(e.message);
896	      return 1;
897	    }
898	    throw e;
899	  }
900	  const alert = state.alerts.find((a) => a.id === alertId);
901	  if (!alert) {
902	    err(`unknown alert '${alertId}'`);
903	    return 1;
904	  }
905	  if (alert.acknowledged) {
906	    console.log(`alert ${alert.id} already acknowledged; unchanged`);
907	    return 0;
908	  }
909	  alert.acknowledged = true;
910	  alert.events.push({ seq: state.nextEventSeq++, type: 'acknowledged' });
911	  try {
912	    saveAlertState(statePath, state);
913	  } catch (e) {
914	    if (e instanceof StoreError) {
915	      err(e.message);
916	      return 1;
917	    }
918	    throw e;
919	  }
920	  const rule = state.rules.find((r) => r.id === alert.ruleId);
921	  const target = rule ? ` ${targetLabel(rule)}` : '';
922	  console.log(
923	    `alert ${alert.id} acknowledged (rule=${alert.ruleId}${target} date=${alert.date} status=${alert.status})`,
924	  );
925	  return 0;
926	}
