1	// 命名时区分日:用运行环境自带的 Intl(ECMA-402)解析 IANA 时区,
2	// 按当地墙钟把查询范围切成自然日。不按固定 86400 秒或全年固定偏移
3	// 推算日界线:夏令时前拨跳过的当天更短(跳过的小时不存在,不补为未知),
4	// 回拨当天更长(重复小时按各自实际时刻完整计入);同一当地日期在不连续
5	// 时段出现时合并统计、时段分别保留;整日被跳过的当地日期没有实际时段,
6	// 不生成虚构日报。
7	
8	import { formatIsoUtc, parseUtcDate } from './time.ts';
9	
10	export interface LocalDayPeriod {
11	  /** 时段起点(含),epoch 秒。 */
12	  start: number;
13	  /** 时段终点(不含),epoch 秒。 */
14	  end: number;
15	}
16	
17	export interface LocalDay {
18	  /** 当地日期标签,YYYY-MM-DD。 */
19	  label: string;
20	  /** 该当地日期在查询范围内的实际 UTC 时段,按时间升序、互不重叠。 */
21	  periods: LocalDayPeriod[];
22	}
23	
24	interface WallClock {
25	  /** 日期比较键,y*10000+m*100+d。 */
26	  key: number;
27	  /** 日期标签,YYYY-MM-DD。 */
28	  label: string;
29	  /** 墙钟分量按 UTC 解释的 epoch 秒(用于偏移与午夜推算)。 */
30	  naive: number;
31	  /** 下一个当地午夜的墙钟,按 UTC 解释的 epoch 秒。 */
32	  nextMidnight: number;
33	}
34	
35	/** 校验 IANA 时区名并构造墙钟格式化器;运行环境不支持时返回 null。 */
36	export function loadTimezone(name: string): Intl.DateTimeFormat | null {
37	  if (name === '') return null;
38	  try {
39	    const fmt = new Intl.DateTimeFormat('en-US', {
40	      timeZone: name,
41	      year: 'numeric',
42	      month: '2-digit',
43	      day: '2-digit',
44	      hour: '2-digit',
45	      minute: '2-digit',
46	      second: '2-digit',
47	      hourCycle: 'h23',
48	    });
49	    fmt.format(0);
50	    return fmt;
51	  } catch {
52	    return null;
53	  }
54	}
55	
56	/**
57	 * 把时区名解析为运行环境解析后的规范 IANA 名称(如 US/Eastern 解析为
58	 * America/New_York);运行环境不支持时返回 null。同一实际时区的不同写法
59	 * 解析为同一规范名,规则时区按规范名存储与比较。
60	 */
61	export function canonicalTimezone(name: string): string | null {
62	  const fmt = loadTimezone(name);
63	  if (fmt === null) return null;
64	  const resolved = fmt.resolvedOptions().timeZone;
65	  return typeof resolved === 'string' && resolved !== '' ? resolved : null;
66	}
67	
68	/** 年月日时分秒按 UTC 解释的 epoch 秒(setUTCFullYear 以支持 0-99 年)。 */
69	function naiveEpoch(y: number, mo: number, d: number, h: number, mi: number, s: number): number {
70	  const dt = new Date(0);
71	  dt.setUTCFullYear(y, mo - 1, d);
72	  dt.setUTCHours(h, mi, s, 0);
73	  return dt.getTime() / 1000;
74	}
75	
76	/** 时刻 t 在时区 fmt 下的墙钟。 */
77	function wallClock(fmt: Intl.DateTimeFormat, t: number): WallClock {
78	  let y = 0;
79	  let mo = 0;
80	  let d = 0;
81	  let h = 0;
82	  let mi = 0;
83	  let s = 0;
84	  for (const p of fmt.formatToParts(t * 1000)) {
85	    switch (p.type) {
86	      case 'year':
87	        y = Number(p.value);
88	        break;
89	      case 'month':
90	        mo = Number(p.value);
91	        break;
92	      case 'day':
93	        d = Number(p.value);
94	        break;
95	      case 'hour':
96	        h = Number(p.value);
97	        break;
98	      case 'minute':
99	        mi = Number(p.value);
100	        break;
101	      case 'second':
102	        s = Number(p.value);
103	        break;
104	    }
105	  }
106	  const pad = (n: number): string => String(n).padStart(2, '0');
107	  return {
108	    key: y * 10000 + mo * 100 + d,
109	    label: `${String(y).padStart(4, '0')}-${pad(mo)}-${pad(d)}`,
110	    naive: naiveEpoch(y, mo, d, h, mi, s),
111	    nextMidnight: naiveEpoch(y, mo, d, 0, 0, 0) + 86400,
112	  };
113	}
114	
115	/** 时区在时刻 t 的偏移(墙钟 - UTC),秒。 */
116	function offsetAt(fmt: Intl.DateTimeFormat, t: number): number {
117	  return wallClock(fmt, t).naive - t;
118	}
119	
120	/**
121	 * 在 (t, limit] 内找第一个偏移与 o0 不同的时刻;没有返回 Infinity。
122	 * 先按小时步进定位再秒级二分;IANA 时区的相邻偏移切换间隔远大于一小时,
123	 * 一小时内两次切换且净偏移不变的情形不存在。
124	 */
125	function nextTransition(fmt: Intl.DateTimeFormat, t: number, o0: number, limit: number): number {
126	  let lo = t;
127	  let u = t;
128	  while (u < limit) {
129	    u = Math.min(u + 3600, limit);
130	    if (offsetAt(fmt, u) !== o0) {
131	      let hi = u;
132	      while (hi - lo > 1) {
133	        const mid = Math.floor((lo + hi) / 2);
134	        if (offsetAt(fmt, mid) !== o0) hi = mid;
135	        else lo = mid;
136	      }
137	      return hi;
138	    }
139	    lo = u;
140	  }
141	  return Infinity;
142	}
143	
144	/**
145	 * 把 [from, to) 按当地自然日切分。返回按首次出现排序(即日期升序)的
146	 * 当地日期,每个日期带实际统计的 UTC 时段;同一日期的不连续时段合并到
147	 * 同一日期下分别列出,相邻时段并为一个区间。没有实际时段的当地日期
148	 * (如整体被跳过的日期)不出现。
149	 */
150	export function localDays(fmt: Intl.DateTimeFormat, from: number, to: number): LocalDay[] {
151	  const days: LocalDay[] = [];
152	  const byKey = new Map<number, LocalDay>();
153	  let cursor = from;
154	  while (cursor < to) {
155	    const w = wallClock(fmt, cursor);
156	    const o0 = w.naive - cursor;
157	    // 偏移不变时下一次日期变化的 UTC 时刻;wall(cursor) < nextMidnight,
158	    // 故 uStar > cursor 恒成立。
159	    const uStar = w.nextMidnight - o0;
160	    // 偏移切换可能先于午夜到达(如午夜前后切换夏令时),此时日期是否变化
161	    // 由下一轮以新偏移重新计算;段内偏移恒定,日期不会中途改变。
162	    const trans = nextTransition(fmt, cursor, o0, Math.min(uStar, to));
163	    const end = Math.min(uStar, trans, to);
164	    let day = byKey.get(w.key);
165	    if (!day) {
166	      day = { label: w.label, periods: [] };
167	      byKey.set(w.key, day);
168	      days.push(day);
169	    }
170	    const last = day.periods[day.periods.length - 1];
171	    if (last && last.end === cursor) last.end = end;
172	    else day.periods.push({ start: cursor, end });
173	    cursor = end;
174	  }
175	  return days;
176	}
177	
178	export interface WallSegment {
179	  /** 段起点(含),epoch 秒。 */
180	  start: number;
181	  /** 段终点(不含),epoch 秒。 */
182	  end: number;
183	  /** 段内当地日期标签,YYYY-MM-DD。 */
184	  label: string;
185	  /** 段内恒定偏移(墙钟 - UTC),秒。 */
186	  offset: number;
187	}
188	
189	/**
190	 * 把 [from, to) 切成偏移恒定、当地日期单一的最细时段:在当地午夜与偏移
191	 * 切换(夏令时)处切开,不像 localDays 那样把同日的相邻段合并。段内墙钟
192	 * 随 UTC 线性平移(wall = utc + offset),供按当地墙钟分类的口径使用。
193	 */
194	export function wallSegments(fmt: Intl.DateTimeFormat, from: number, to: number): WallSegment[] {
195	  const segs: WallSegment[] = [];
196	  let cursor = from;
197	  while (cursor < to) {
198	    const w = wallClock(fmt, cursor);
199	    const o0 = w.naive - cursor;
200	    const uStar = w.nextMidnight - o0;
201	    const trans = nextTransition(fmt, cursor, o0, Math.min(uStar, to));
202	    const end = Math.min(uStar, trans, to);
203	    segs.push({ start: cursor, end, label: w.label, offset: o0 });
204	    cursor = end;
205	  }
206	  return segs;
207	}
208	
209	export interface LocalDateEntry {
210	  /** 当地日期标签,YYYY-MM-DD,按当地日期升序。 */
211	  label: string;
212	  /** 归属该日期的全部实际 UTC 时段;null 表示整日被跳过(无实际时段)。 */
213	  day: LocalDay | null;
214	}
215	
216	/**
217	 * 把连续日历日期范围 [fromLabel, toLabel)(YYYY-MM-DD,起日含、止日不含)映射为
218	 * 各当地日期在 fmt 时区下的实际 UTC 时段。每个日期统计归属该日期的全部实际
219	 * 时段,不把当地午夜简单套用固定偏移:夏令时短日的实际时段更短,回拨日更长,
220	 * 日期回退产生的不连续时段合并在同一日期下;整日被跳过的日期 day 为 null,
221	 * 由调用方标明跳过。日历日期本身按格里历逐日递增,与时区无关。
222	 */
223	export function localDateRange(
224	  fmt: Intl.DateTimeFormat,
225	  fromLabel: string,
226	  toLabel: string,
227	): LocalDateEntry[] {
228	  const fromUtc = parseUtcDate(fromLabel) as number;
229	  const toUtc = parseUtcDate(toLabel) as number;
230	  // 任一日期的当地午夜与 UTC 午夜之差不超过该时区的最大偏移(远小于两天),
231	  // 向两侧放宽后再切分,保证首尾日期的实际时段完整落入切分范围。
232	  const margin = 2 * 86400;
233	  const days = localDays(fmt, fromUtc - margin, toUtc + margin);
234	  const byLabel = new Map<string, LocalDay>();
235	  for (const d of days) byLabel.set(d.label, d);
236	  const out: LocalDateEntry[] = [];
237	  for (let t = fromUtc; t < toUtc; t += 86400) {
238	    const label = formatIsoUtc(t).slice(0, 10);
239	    out.push({ label, day: byLabel.get(label) ?? null });
240	  }
241	  return out;
242	}
