1	// daily 子命令:按当地自然日核查能耗的只读日报,默认 UTC,可用 --tz 指定
2	// 运行环境支持的 IANA 时区。时区只决定分日,不重新解释输入时刻或已存读数。
3	//
4	// 估算口径:
5	// - 区间由每个设备完整已存时序的相邻读数构成,两端读数即使在查询范围外
6	//   也参与;范围内没有读数但被区间覆盖时仍得到结果。
7	// - 非下降区间把累计值之差按持续时间均匀分摊:以千分之一 kWh 为单位,
8	//   从区间起点累计到任一切点 t 的比例量为 floor(diff*(t-start)/duration),
9	//   片段消耗为终点与起点累计量之差。切点为查询边界与当地日界线,因此
10	//   完整区间的分摊总量等于原差值,同一区间拆开查询再相加结果一致;
11	//   新的日界线不重置分摊起点。
12	// - 中间乘积与多区间汇总使用 BigInt,超过 Number 安全整数范围仍精确。
13	// - 下降区间不分摊消耗,记为异常覆盖;其后的区间仍从下降后的读数计算。
14	// - 首条读数之前、末条之后及孤立读数时段为未知,不外推。
15	// - 可选的最大采样间隔限制(正整数秒):非下降相邻区间的实际时间差超过
16	//   限制时,整个区间视为未知,不分摊消耗;等于限制仍可信。区间按完整已存
17	//   时序判定,不因查询范围、当地日界线或成员切换被裁短而变成可信区间;
18	//   下降区间即使超过限制仍为异常。
19	// - 日界线按实际时刻的当地日期归属计算,不用固定 86400 秒或固定偏移推算:
20	//   夏令时前拨当天更短(跳过的小时不补为未知),回拨当天更长(重复小时按
21	//   各自实际时刻完整计入);同一当地日期的不连续时段合并统计、分别列出;
22	//   没有实际时段的当地日期不生成日报。
23	
24	import { loadStore, StoreError, dataFilePath, type Reading } from './store.ts';
25	import { formatIsoUtc } from './time.ts';
26	import { localDays, loadTimezone, type LocalDay } from './tz.ts';
27	import { formatKwh } from './value.ts';
28	
29	export interface DailyFilter {
30	  devices: string[];
31	  /** 查询起点(含),epoch 秒。 */
32	  from: number;
33	  /** 查询终点(不含),epoch 秒。 */
34	  to: number;
35	  /** 分日时区(IANA 名称);省略时按 UTC。 */
36	  tz?: string;
37	  /** 最大采样间隔限制(正整数秒);省略表示无上限。只影响本次查询结果。 */
38	  maxInterval?: number;
39	}
40	
41	export const DAY_SECONDS = 86400;
42	
43	function err(message: string): void {
44	  console.error(`meterwatch: ${message}`);
45	}
46	
47	export interface GapDetail {
48	  /** 相关设备标识;单设备日报中由上下文给出时可为空。 */
49	  device?: string;
50	  /** 过长区间两端原始读数时刻(完整已存时序中的相邻读数),epoch 秒。 */
51	  start: number;
52	  end: number;
53	}
54	
55	export interface DayStats {
56	  /** 有效(非下降且未超采样间隔限制的区间)覆盖秒数。 */
57	  valid: number;
58	  /** 异常(下降区间)覆盖秒数。 */
59	  anomaly: number;
60	  /** 未知(无区间覆盖或区间超过采样间隔限制)秒数。 */
61	  unknown: number;
62	  /** unknown 中由超过采样间隔限制的相邻区间造成的秒数(子集,单独区分显示)。 */
63	  gapUnknown: number;
64	  /** 与统计范围相交的过长区间明细(原始相邻读数时刻),已去重。 */
65	  gaps: GapDetail[];
66	  /** 该天分摊消耗,毫千瓦时;仅 valid > 0 时有意义。 */
67	  consumption: bigint;
68	}
69	
70	/** 合并过长区间明细,按设备、起点、终点去重(保持首次出现顺序)。 */
71	export function mergeGaps(into: GapDetail[], add: GapDetail[]): void {
72	  const seen = new Set(into.map((g) => `${g.device ?? ''} ${g.start} ${g.end}`));
73	  for (const g of add) {
74	    const key = `${g.device ?? ''} ${g.start} ${g.end}`;
75	    if (!seen.has(key)) {
76	      seen.add(key);
77	      into.push(g);
78	    }
79	  }
80	}
81	
82	/**
83	 * 计算 [segStart, segEnd) 一天的统计;区间取自完整时序。
84	 * maxInterval 为可选的最大采样间隔限制(秒):非下降区间的实际时间差超过
85	 * 限制时整个区间记为未知(不按统计范围裁短),等于限制仍可信;下降区间
86	 * 即使超过限制仍为异常。
87	 */
88	export function computeDay(
89	  series: Reading[],
90	  segStart: number,
91	  segEnd: number,
92	  maxInterval?: number,
93	): DayStats {
94	  let valid = 0;
95	  let anomaly = 0;
96	  let gapUnknown = 0;
97	  const gaps: GapDetail[] = [];
98	  let consumption = 0n;
99	  for (let i = 1; i < series.length; i++) {
100	    const a = series[i - 1];
101	    const b = series[i];
102	    const lo = Math.max(a.ts, segStart);
103	    const hi = Math.min(b.ts, segEnd);
104	    if (lo >= hi) continue;
105	    const diff = b.milli - a.milli;
106	    if (diff < 0n) {
107	      anomaly += hi - lo;
108	    } else if (maxInterval !== undefined && b.ts - a.ts > maxInterval) {
109	      gapUnknown += hi - lo;
110	      gaps.push({ start: a.ts, end: b.ts });
111	    } else {
112	      valid += hi - lo;
113	      const duration = BigInt(b.ts - a.ts);
114	      const total = diff;
115	      // 从区间起点累计到 t 的比例量(向下取整);BigInt 除法向零截断,
116	      // 被除数非负,等价于向下取整。
117	      const cumulative = (t: number): bigint => (total * BigInt(t - a.ts)) / duration;
118	      consumption += cumulative(hi) - cumulative(lo);
119	    }
120	  }
121	  const unknown = segEnd - segStart - valid - anomaly;
122	  return { valid, anomaly, unknown, gapUnknown, gaps, consumption };
123	}
124	
125	/** 汇总一天内各 UTC 时段的统计;三类秒数之和等于这些时段的总秒数。 */
126	function sumDayStats(series: Reading[], day: LocalDay, maxInterval?: number): DayStats {
127	  let valid = 0;
128	  let anomaly = 0;
129	  let unknown = 0;
130	  let gapUnknown = 0;
131	  const gaps: GapDetail[] = [];
132	  let consumption = 0n;
133	  for (const p of day.periods) {
134	    const s = computeDay(series, p.start, p.end, maxInterval);
135	    valid += s.valid;
136	    anomaly += s.anomaly;
137	    unknown += s.unknown;
138	    gapUnknown += s.gapUnknown;
139	    mergeGaps(gaps, s.gaps);
140	    consumption += s.consumption;
141	  }
142	  return { valid, anomaly, unknown, gapUnknown, gaps, consumption };
143	}
144	
145	/** 采用的采样间隔限制的展示形式(省略为无上限)。 */
146	export function maxIntervalText(maxInterval?: number): string {
147	  return maxInterval === undefined ? 'none' : `${maxInterval}s`;
148	}
149	
150	/** 过长区间明细的展示行(指出相关设备与原始相邻读数时刻)。 */
151	export function formatGapLine(gap: GapDetail, device?: string): string {
152	  const dev = gap.device ?? device ?? '?';
153	  return `    gap: device=${dev}  interval=${formatIsoUtc(gap.start)}..${formatIsoUtc(gap.end)}`;
154	}
155	
156	/**
157	 * 输出按当地自然日划分的能耗日报。只读,不修改数据。
158	 * 同设备同一实际时刻存在多条存储记录时报错并返回 1。
159	 * 返回进程退出码。
160	 */
161	export function cmdDaily(filter: DailyFilter): number {
162	  const tzName = filter.tz ?? 'UTC';
163	  const tz = loadTimezone(tzName);
164	  if (!tz) {
165	    err(`unknown timezone '${tzName}' (expect an IANA timezone name supported by this runtime)`);
166	    return 2;
167	  }
168	  const days = localDays(tz, filter.from, filter.to);
169	
170	  const storePath = dataFilePath();
171	  let all: Reading[];
172	  try {
173	    all = loadStore(storePath);
174	  } catch (e) {
175	    if (e instanceof StoreError) {
176	      err(e.message);
177	      return 1;
178	    }
179	    throw e;
180	  }
181	
182	  const byDevice = new Map<string, Reading[]>();
183	  for (const r of all) {
184	    const list = byDevice.get(r.device);
185	    if (list) list.push(r);
186	    else byDevice.set(r.device, [r]);
187	  }
188	  for (const [device, list] of byDevice) {
189	    list.sort((a, b) => a.ts - b.ts);
190	    for (let i = 1; i < list.length; i++) {
191	      if (list[i].ts === list[i - 1].ts) {
192	        err(
193	          `storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(list[i].ts)}`,
194	        );
195	        return 1;
196	      }
197	    }
198	  }
199	
200	  const wanted =
201	    filter.devices.length > 0 ? [...new Set(filter.devices)] : [...byDevice.keys()];
202	  wanted.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
203	
204	  console.log(`timezone: ${tzName}`);
205	  console.log(`max-interval: ${maxIntervalText(filter.maxInterval)}`);
206	  let printed = false;
207	  for (const device of wanted) {
208	    const series = byDevice.get(device);
209	    if (!series) continue;
210	    printed = true;
211	
212	    console.log(`device: ${device}`);
213	    let total = 0n;
214	    let computedDays = 0;
215	    let incomplete = false;
216	    for (const day of days) {
217	      const stats = sumDayStats(series, day, filter.maxInterval);
218	      const dayIncomplete = stats.anomaly > 0 || stats.unknown > 0;
219	      if (dayIncomplete) incomplete = true;
220	
221	      let consumption: string;
222	      if (stats.valid > 0) {
223	        consumption = `consumption=${formatKwh(stats.consumption)} kWh (estimate)`;
224	        total += stats.consumption;
225	        computedDays++;
226	      } else {
227	        consumption = 'consumption=n/a (no valid coverage)';
228	      }
229	      let line =
230	        `  ${day.label}  ${consumption}` +
231	        `  valid=${stats.valid}s  anomaly=${stats.anomaly}s  unknown=${stats.unknown}s`;
232	      if (filter.maxInterval !== undefined) line += `  gap=${stats.gapUnknown}s`;
233	      if (dayIncomplete) line += '  INCOMPLETE';
234	      console.log(line);
235	      for (const p of day.periods) {
236	        console.log(`    period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`);
237	      }
238	      for (const g of stats.gaps) {
239	        console.log(formatGapLine(g, device));
240	      }
241	    }
242	
243	    const totalText =
244	      computedDays > 0
245	        ? `total consumption=${formatKwh(total)} kWh (estimate)`
246	        : 'total consumption=n/a (no valid coverage)';
247	    const status = incomplete
248	      ? 'status=INCOMPLETE (unknown or anomaly coverage present)'
249	      : 'status=complete';
250	    console.log(
251	      `  summary: device=${device}  computed=${computedDays}/${days.length} day(s)  ${totalText}  ${status}`,
252	    );
253	  }
254	  if (!printed) console.log('no matching devices');
255	  return 0;
256	}
