15	  device: string;
16	  /** 实际时刻,epoch 秒。 */
17	  ts: number;
18	  /** 累计读数,毫千瓦时(千分之一 kWh)BigInt,非负。 */
19	  milli: bigint;
20	}
21	
22	export interface CorrectionItem {
23	  /** 设备标识(已去除首尾空白,区分大小写)。 */
24	  device: string;
25	  /** 实际时刻,epoch 秒。 */
26	  ts: number;
27	  /** 提交时核验的预期原值,毫千瓦时 BigInt。 */
28	  expectedMilli: bigint;
29	  /** 替换值,毫千瓦时 BigInt。 */
30	  replacementMilli: bigint;
31	}
32	
33	export interface Correction {
34	  /** 请求标识(已去除首尾空白,区分大小写),在数据目录内唯一。 */
35	  requestId: string;
36	  /** 本次提交的修正项,按提交顺序保存。 */
37	  items: CorrectionItem[];
38	}
