305	/** 解析最大采样间隔限制(正整数秒数);无效返回 null。 */
306	function parseMaxInterval(raw: string): number | null {
307	  const v = raw.trim();
308	  if (!/^\d+$/.test(v)) return null;
309	  const n = Number(v);
