314	/** 解析 --device/--from/--to(及允许时的 --tz、--max-interval)选项;出错返回错误消息字符串。 */
315	function parseOptions(rest: string[], allowTz = false, allowMaxInterval = false): ParsedOptions | string {
316	  const devices: string[] = [];
317	  let from: number | undefined;
318	  let to: number | undefined;
319	  let tz: string | undefined;
320	  let maxInterval: number | undefined;
321	  for (let i = 0; i < rest.length; i++) {
322	    let opt = rest[i];
323	    let value: string | undefined;
324	    const eq = opt.indexOf('=');
325	    if (opt.startsWith('--') && eq !== -1) {
326	      value = opt.slice(eq + 1);
327	      opt = opt.slice(0, eq);
328	    } else if (opt.startsWith('--')) {
329	      value = rest[i + 1];
330	      if (value === undefined) return `选项 '${opt}' 缺少值`;
331	      i++;
332	    } else {
333	      return `无法识别的参数 '${opt}'`;
334	    }
335	    if (opt === '--device') {
336	      if (value.trim() === '') return "'--device' 的值不能为空";
337	      devices.push(value);
338	    } else if (opt === '--from' || opt === '--to') {
339	      const ts = parseIso8601(value.trim());
340	      if (ts === null) {
341	        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
342	      }
343	      if (opt === '--from') from = ts;
344	      else to = ts;
345	    } else if (opt === '--tz' && allowTz) {
346	      tz = value.trim();
347	      if (tz === '') return "'--tz' 的值不能为空";
348	    } else if (opt === '--max-interval' && allowMaxInterval) {
349	      const n = parseMaxInterval(value);
350	      if (n === null) {
351	        return `选项 '--max-interval' 的值无效: '${value.trim()}'(需正整数秒数)`;
352	      }
353	      maxInterval = n;
354	    } else {
355	      return `无法识别的选项 '${opt}'`;
356	    }
357	  }
358	  return { devices, from, to, tz, maxInterval };
359	}
