362	function checkTz(tz: string): string | null {
363	  if (loadTimezone(tz) === null) {
364	    return `未知时区 '${tz}'(需运行环境支持的 IANA 时区名,如 Asia/Shanghai、America/New_York)`;
365	  }
366	  return null;
