369	/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
370	function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
371	  const out = new Map<string, string[]>();
372	  for (let i = 0; i < rest.length; i++) {
373	    let opt = rest[i];
374	    let value: string | undefined;
375	    const eq = opt.indexOf('=');
376	    if (opt.startsWith('--') && eq !== -1) {
377	      value = opt.slice(eq + 1);
378	      opt = opt.slice(0, eq);
379	    } else if (opt.startsWith('--')) {
380	      value = rest[i + 1];
381	      if (value === undefined) return `选项 '${opt}' 缺少值`;
382	      i++;
383	    } else {
384	      return `无法识别的参数 '${opt}'`;
385	    }
386	    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
387	    const list = out.get(opt);
388	    if (list) list.push(value);
389	    else out.set(opt, [value]);
390	  }
391	  return out;
392	}
