712	    return "'correct' 需要至少一个 --item(--item --device <设备> --at <iso> --expect <kWh> --set <kWh>)";
713	  }
714	  const items: CorrectionItem[] = [];
715	  for (const seg of itemSegs) {
716	    const flags = parseFlags(seg, ['--device', '--at', '--expect', '--set']);
