727	    const ts = parseIso8601(atRaw.trim());
728	    if (ts === null) {
729	      return `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
730	    }
