740	  }
741	  return { requestId, items };
742	}
743	
744	function cmdCorrectEntry(rest: string[]): number {
745	  const parsed = parseCorrectItems(rest);
746	  if (typeof parsed === 'string') return usageError(parsed);
747	  return cmdCorrect(parsed.requestId, parsed.items);
748	}
749	
750	function cmdUndoEntry(rest: string[]): number {
751	  const flags = parseFlags(rest, ['--request', '--target']);
752	  if (typeof flags === 'string') return usageError(flags);
753	  const requestRaw = oneFlag(flags, '--request');
754	  const targetRaw = oneFlag(flags, '--target');
755	  if (requestRaw === null || targetRaw === null) {
756	    return usageError("'undo' 需要 --request 与 --target 各恰好一个");
757	  }
758	  const requestId = requestRaw.trim();
759	  if (requestId === '') return usageError('撤销请求标识不能为空');
760	  const targetId = targetRaw.trim();
761	  if (targetId === '') return usageError('目标修正请求标识不能为空');
762	  return cmdUndo(requestId, targetId);
763	}
764	
765	function main(args: string[]): number {
766	  // 所有入口(含无参数、--help/-h、非法参数)都先取得数据目录操作权并处理
767	  // 未完成恢复,再执行查询或写入;协调失败返回 1,不输出正常业务结果。
768	  const result = withDirectoryCoordination<number>(() => runCommand(args));
769	  return typeof result === 'number' ? result : 1;
770	}
771	
772	function runCommand(args: string[]): number {
773	  if (args.length === 0) {
774	    console.log(help);
775	    return 0;
776	  }
777	  const [cmd, ...rest] = args;
778	  if (rest.length === 0 && (cmd === '--help' || cmd === '-h')) {
779	    console.log(help);
780	    return 0;
781	  }
782	
783	  if (cmd === 'import') {
784	    if (rest.length !== 1) return usageError("'import' 需要且仅需要一个 CSV 文件路径");
785	    return cmdImport(rest[0]);
786	  }
787	
788	  if (cmd === 'readings') {
789	    const parsed = parseOptions(rest);
790	    if (typeof parsed === 'string') return usageError(parsed);
791	    if (parsed.from !== undefined && parsed.to !== undefined && parsed.from >= parsed.to) {
792	      return usageError('查询起点必须早于终点(--from < --to)');
793	    }
794	    return cmdReadings(parsed);
795	  }
796	
797	  if (cmd === 'daily') {
798	    const parsed = parseOptions(rest, true, true);
799	    if (typeof parsed === 'string') return usageError(parsed);
800	    if (parsed.from === undefined || parsed.to === undefined) {
801	      return usageError("'daily' 必须同时提供 --from 与 --to(起点含、终点不含)");
802	    }
803	    if (parsed.from >= parsed.to) {
804	      return usageError('查询起点必须早于终点(--from < --to)');
805	    }
806	    if (parsed.tz !== undefined) {
807	      const bad = checkTz(parsed.tz);
808	      if (bad !== null) return usageError(bad);
809	    }
810	    return cmdDaily({
811	      devices: parsed.devices,
812	      from: parsed.from,
813	      to: parsed.to,
814	      tz: parsed.tz,
815	      maxInterval: parsed.maxInterval,
816	    });
817	  }
818	
819	  if (cmd === 'rule') return cmdRule(rest);
820	  if (cmd === 'evaluate') return cmdEvaluateEntry(rest);
821	  if (cmd === 'alerts') return cmdAlertsEntry(rest);
822	  if (cmd === 'group') return cmdGroup(rest);
823	  if (cmd === 'correct') return cmdCorrectEntry(rest);
824	  if (cmd === 'undo') return cmdUndoEntry(rest);
825	
826	  if (cmd === 'corrections') {
827	    if (rest.length !== 0) return usageError("'corrections' 不接受参数");
828	    return cmdCorrections();
829	  }
830	
831	  if (cmd === 'ack') {
832	    if (rest.length !== 1) return usageError("'ack' 需要且仅需要一个告警标识");
833	    const alertId = rest[0].trim();
834	    if (alertId === '') return usageError('告警标识不能为空');
835	    return cmdAck(alertId);
836	  }
837	
838	  if (cmd === 'backup') {
839	    if (rest.length !== 1) return usageError("'backup' 需要且仅需要一个快照文件路径(须位于数据目录之外)");
840	    return cmdBackup(rest[0]);
841	  }
842	
843	  if (cmd === 'restore') {
844	    if (rest.length !== 1) return usageError("'restore' 需要且仅需要一个快照文件路径(须位于数据目录之外)");
845	    return cmdRestore(rest[0]);
846	  }
847	
848	  return usageError(`无法识别的参数 '${cmd}'`);
849	}
850	
851	process.exitCode = main(process.argv.slice(2));
