node -e '
const ep = (s) => Date.parse(s) / 1000;
const T0 = ep("2026-01-04T00:00:00Z");
const U0 = ep("2026-01-05T00:00:00Z");
const D1 = 9007199254741001n, dur1 = 172800n;
const D2 = 1000001n, dur2 = 86400n;
const cum1 = (t) => (D1 * BigInt(t - T0)) / dur1;
const cum2 = (t) => (D2 * BigInt(t - U0)) / dur2;
const cum2b = (t) => (1000000n * BigInt(t - U0)) / dur2; // after correction

const day = U0;
const sw = day + 21630;          // 06:00:30 member switch
const w08 = day + 28800;         // 08:00 window start
const w18 = day + 64800;         // 18:00 window end
const end = day + 86400;

const m1_A1 = cum1(sw) - cum1(day);
const m1_A2 = cum1(w08) - cum1(sw);
const m2_A2 = cum2(w08) - cum2(sw);
const m1_B  = cum1(end) - cum1(w18);
const m2_B  = cum2(end) - cum2(w18);
const total = m1_A1 + m1_A2 + m2_A2 + m1_B + m2_B;
console.log("m1_A1", m1_A1.toString());
console.log("m1_A2", m1_A2.toString());
console.log("m2_A2", m2_A2.toString());
console.log("m1_B ", m1_B.toString());
console.log("m2_B ", m2_B.toString());
console.log("TOTAL", total.toString(), "kWh", Number(total/1000n) + "." + (total%1000n).toString().padStart(3,"0"));

const m2_A2c = cum2b(w08) - cum2b(sw);
const m2_Bc  = cum2b(end) - cum2b(w18);
const totalC = m1_A1 + m1_A2 + m2_A2c + m1_B + m2_Bc;
console.log("m2_A2 corrected", m2_A2c.toString());
console.log("m2_B  corrected", m2_Bc.toString());
console.log("TOTAL corrected", totalC.toString());

// NY spring forward 2026-03-08: interval [03-07T00:00Z, 03-10T00:00Z] diff 3000 dur 259200
const S0 = ep("2026-03-07T00:00:00Z");
const cumS = (t) => (3000n * BigInt(t - S0)) / 259200n;
const spr = cumS(ep("2026-03-09T04:00:00Z")) - cumS(ep("2026-03-08T05:00:00Z"));
console.log("spring day seconds", ep("2026-03-09T04:00:00Z") - ep("2026-03-08T05:00:00Z"), "consumption", spr.toString());

// NY fall back 2026-11-01: interval [10-31T00:00Z, 11-03T00:00Z] diff 3000 dur 259200
const F0 = ep("2026-10-31T00:00:00Z");
const cumF = (t) => (3000n * BigInt(t - F0)) / 259200n;
const f1 = cumF(ep("2026-11-01T05:00:00Z")) - cumF(ep("2026-11-01T04:00:00Z"));
const f2 = cumF(ep("2026-11-02T05:00:00Z")) - cumF(ep("2026-11-01T07:00:00Z"));
console.log("fall day seconds", ep("2026-11-02T05:00:00Z") - ep("2026-11-01T04:00:00Z"));
console.log("fall frag1", f1.toString(), "frag2", f2.toString(), "total", (f1+f2).toString());
'

